import { Component, OnInit } from '@angular/core';
import { ApiService } from '../services/api.service';
import { Course } from '../models/models';

@Component({
  selector: 'app-courses',
  templateUrl: './courses.component.html',
})
export class CoursesComponent implements OnInit {
  courses: Course[] = [];
  loading = true;
  error = '';
  showForm = false;
  editing: Course | null = null;
  form = { title: '', code: '' };
  submitting = false;

  constructor(private api: ApiService) {}

  ngOnInit(): void { this.load(); }

  load(): void {
    this.loading = true;
    this.api.getCourses().subscribe({
      next: (data) => { this.courses = data; this.loading = false; },
      error: () => { this.error = 'Failed to load courses.'; this.loading = false; },
    });
  }

  openAdd(): void {
    this.editing = null;
    this.form = { title: '', code: '' };
    this.error = '';
    this.showForm = true;
  }

  openEdit(c: Course): void {
    this.editing = c;
    this.form = { title: c.title, code: c.code };
    this.error = '';
    this.showForm = true;
  }

  cancel(): void {
    this.showForm = false;
    this.editing = null;
    this.error = '';
  }

  submit(): void {
    this.submitting = true;
    this.error = '';
    const req = this.editing
      ? this.api.updateCourse(this.editing.id, this.form)
      : this.api.createCourse(this.form);

    req.subscribe({
      next: () => { this.cancel(); this.load(); this.submitting = false; },
      error: (err) => {
        const msg = err.error?.message;
        this.error = Array.isArray(msg) ? msg.join(', ') : (msg || 'An error occurred.');
        this.submitting = false;
      },
    });
  }

  deleteCourse(c: Course): void {
    if (!confirm(`Delete course "${c.title} (${c.code})"?\nThis will also delete all assignments and remove all enrollments.`)) return;
    this.api.deleteCourse(c.id).subscribe({
      next: () => this.load(),
      error: () => { this.error = 'Failed to delete course.'; },
    });
  }
}
<div class="container">
  <div class="page-header">
    <h2>Courses</h2>
    <button class="btn btn-primary" (click)="openAdd()">+ Add Course</button>
  </div>

  <div *ngIf="error && !showForm" class="alert-error">{{ error }}</div>

  <div *ngIf="showForm" class="card form-card">
    <h3>{{ editing ? 'Edit Course' : 'New Course' }}</h3>
    <div *ngIf="error" class="alert-error">{{ error }}</div>
    <form (ngSubmit)="submit()" #f="ngForm">
      <div class="form-row">
        <div class="form-group">
          <label>Course Title</label>
          <input required name="title" [(ngModel)]="form.title" placeholder="e.g. Introduction to Programming" />
        </div>
        <div class="form-group">
          <label>Course Code</label>
          <input required name="code" [(ngModel)]="form.code" placeholder="e.g. CS101" />
        </div>
      </div>
      <div class="form-actions">
        <button type="submit" class="btn btn-primary" [disabled]="submitting || f.invalid">
          {{ submitting ? 'Saving…' : (editing ? 'Save Changes' : 'Create Course') }}
        </button>
        <button type="button" class="btn btn-secondary" (click)="cancel()">Cancel</button>
      </div>
    </form>
  </div>

  <div *ngIf="loading" class="loading">Loading courses…</div>

  <div *ngIf="!loading" class="card">
    <div *ngIf="courses.length === 0" class="empty-state">
      No courses yet. Click "+ Add Course" to get started.
    </div>
    <table *ngIf="courses.length > 0">
      <thead>
        <tr>
          <th>Title</th>
          <th>Code</th>
          <th>Assignments</th>
          <th>Enrolled Students</th>
          <th>Actions</th>
        </tr>
      </thead>
      <tbody>
        <tr *ngFor="let c of courses">
          <td>
            <a [routerLink]="['/courses', c.id]" class="table-link">{{ c.title }}</a>
          </td>
          <td><span class="badge badge-purple">{{ c.code }}</span></td>
          <td>
            <span class="badge badge-blue">
              {{ c.assignments?.length ?? 0 }} assignment{{ (c.assignments?.length ?? 0) !== 1 ? 's' : '' }}
            </span>
          </td>
          <td>
            <span class="badge badge-green">
              {{ c.students?.length ?? 0 }} student{{ (c.students?.length ?? 0) !== 1 ? 's' : '' }}
            </span>
          </td>
          <td>
            <div class="actions">
              <a [routerLink]="['/courses', c.id]" class="btn btn-secondary btn-sm">View</a>
              <button class="btn btn-secondary btn-sm" (click)="openEdit(c)">Edit</button>
              <button class="btn btn-danger btn-sm" (click)="deleteCourse(c)">Delete</button>
            </div>
          </td>
        </tr>
      </tbody>
    </table>
  </div>
</div>
